#!/usr/bin/env bash
# Join a worker to the cluster with the bootstrap token generated by the Vagrantfile.
set -euo pipefail

TOKEN="${1:?usage: worker.sh TOKEN CONTROLPLANE_IP}"
CONTROLPLANE_IP="${2:?usage: worker.sh TOKEN CONTROLPLANE_IP}"

if [[ -f /etc/kubernetes/kubelet.conf ]]; then
  exit 0
fi

# Skipping CA pinning is acceptable on an isolated lab network: the CA hash would
# have to travel guest -> host -> guest, and the rsync synced folder is one-way.
kubeadm join "${CONTROLPLANE_IP}:6443" \
  --token "${TOKEN}" \
  --discovery-token-unsafe-skip-ca-verification \
  --node-name "$(hostname)"
